from pathlib import Path
import collections,json,re
root=Path('B1'); out=root/'fix-b1-2'
p=root/'CHANNELS.md'; text=(out/'before/B1/CHANNELS.md').read_text()
rows=[]; changes=[]
drows={'C2.6','C4.4','C7.01','C7.07','C7.08','C7.09','C7.23','C7.24','C8.01','C8.02'}
lines=[]
for line in text.splitlines():
 if not line.startswith('| C') and not line.startswith('| M'):
  lines.append(line);continue
 cells=[c.strip() for c in re.split(r'(?<!\\)\|', line.strip('|'))]
 if len(cells)!=6: raise ValueError(line)
 rid=cells[0].split()[0]; old=cells.copy()
 if rid=='C7.02': cells[3]='N gates direct execve of the shebang script; interpreter-argument/file-read and other input routes remain C7.01/03–08 UNKNOWN'
 if rid=='C7.12': cells[3]='N gates direct execve of native/shebang hooks; invoking a recorded interpreter on a hook file instead inherits C7.01 UNKNOWN'
 if rid=='C7.05':
  cells[4]=cells[4].replace('E1,E2,E16','E1,E2,E12,E16')
  cells[3]='D can deny a new file open only after domain entry; mandatory launch coverage and inherited stdin/FD mediation are not evidenced'
 if rid in drows:
  cells[3]='Conditional file-open primitive only: D can deny the unrecorded open after self-restriction/inheritance; mandatory placement of every interpreter start in D is not evidenced'
  cells[4]+='; [Round 2 evidence](fix-b1-2/evidence-audit.md)'
  cells[5]='If imposed, D denies unrecorded document/project-data file reads; whole-session inheritance also restricts shell and descendant editors; non-file inputs remain unresolved'
 if rid=='C7.24':
  cells[0]='C7.24 Recorded custom dispatcher: file-open route and non-file instruction input without eval/import'
  cells[3]='File-open route: D only after domain entry, mandatory coverage unevidenced; non-file route: stdin, argv/environment, inherited FDs and socket/IPC bytes unmediated by D, UNKNOWN; conventional F/I entries miss custom dispatch'
  cells[5]='File-open denial loses unrecorded data reads; receiving own-rights instructions through other inputs still permits Q1 conditional failure'
 if rid.startswith('C') and cells[2]=='CLOSABLE':
  cells[2]='UNKNOWN'
  cells[3]='Candidate subcontrol: '+cells[3]+'; full R remains unestablished (M1.02/M2.02/M3.02; runtime ports C7.25)'
  if 'fix-b1-2/evidence-audit.md' not in cells[4]: cells[4]+='; [Full R audit](fix-b1-2/evidence-audit.md)'
 if cells!=old: changes.append({'id':rid,'before':old,'after':cells})
 rows.append(cells); lines.append('| '+' | '.join(cells)+' |')
text='\n'.join(lines)+'\n'
counts=collections.Counter(r[2] for r in rows)
text=text.replace(text.splitlines()[0],f"CHANNELS: {counts['CLOSABLE']} closable, 0 closable only by removal, 0 not closable, {counts['TEXT-OPEN']} text-open, {counts['UNKNOWN']} unknown",1)
text=text.replace('CLOSABLE means the named bounded route has an evidenced control, with its stated cost; it is not a claim that the unbuilt composition already satisfies every property.','Each verdict covers its row\'s entire stated requirement. All channel rows retain full R and are UNKNOWN or TEXT-OPEN; documented subcontrols alone do not establish R. The remaining CLOSABLE rows are the separately specified mechanics obligations, not whole-channel or whole-system closure.')
text=text.replace('A CLOSABLE transport row cannot override an UNKNOWN or TEXT-OPEN evaluator or transaction row.','No candidate transport control overrides an UNKNOWN or TEXT-OPEN evaluator, listener or transaction requirement.')
start=text.index('**F** means'); end=text.index('\n\nRevision FX-B1-1',start)
text=text[:start]+'''**F** means a proposed cooperating evaluator checking the immutable descriptor it consumes. **I** means its proposed refusal of unrecorded argument, stream, environment and interactive code. Neither has an evidenced adopter for the own-rights interpreter class here. **D** means the conditional read-open restriction documented by Landlock: handle READ_FILE and permit only the immutable admitted closure after self-restriction or inheritance. The cited source does not establish a mandatory component placing every interpreter start in D. D does not filter argv/environment or revoke already-open FDs, terminal/stdin or arbitrary IPC bytes. Even where domain entry occurs, file-open denial alone leaves those instruction routes open. If imposed on a whole session to obtain inheritance, D also removes unrecorded document/project-data file reads from the shell and descendant editors, not only interpreters. Selective launch coverage and safe retained data access are unestablished. **N** is mandatory execution/mapping policy plus restrictions on native memory execution, memfd and injection. These primitives do not establish the declaration broker or full R. See [round 2 audit](fix-b1-2/evidence-audit.md).

Revision FX-B1-2 supersedes the bounded-channel verdict interpretation and D closure claims in FX-B1-1. The latter's files remain frozen historical evidence. The full requirement R, fixed text and failure conditions are unchanged. C7.24 explicitly includes both file-open and non-file custom-dispatch routes within the existing variant. [Round 2 finding disposition](FIX-B1-2.md).'''+text[end:]
text=text.replace('Documented native execution controls and D can block bounded native/file-open routes.','Documented native controls can block bounded native routes; D can deny a file open only after domain entry, whose mandatory coverage is not established.')
text=text.replace('The concrete custom-dispatch route is C7.24.','The concrete custom-dispatch variant is C7.24, with file-open and non-file routes.')
old='For C7.07/08/24, D blocks the unrecorded file open at the cost of denying unrecorded user-document/project-data reads. Keeping arbitrary admitted full-capability interpreters plus unrestricted unrecorded data reads admits this conditional failure; evaluator-entry checks alone cannot close it. Refusing active document content or genuinely confining code under S2.2-11 are different bounded options. A cooperative evaluator checking conventional file/eval entries is removed from the list of sufficient controls. A data reader returning arbitrary bytes to M would recreate the premise; no such broker is claimed to solve it. No system-wide NOT-CLOSABLE result follows because systems need not retain both capabilities.'
new='For C7.07/08/24, D can block a new unrecorded file open only after domain entry, at the cost of denying unrecorded user-document/project-data file reads. Mandatory entry for every launch is not evidenced. Even if M is in D, an unrestricted reader can send F through stdin (`cat F | M`), an inherited descriptor or a socket; argv/environment can also supply instructions. These are source-based counterroutes to the proposed control, not new probe observations. The explicit premise remains that the received instructions are code executed with M\'s own rights (S2.2-10), rather than mere values; routing those instructions through a pipe does not record them. C7.24 therefore records both the file-open and non-file routes as UNKNOWN. Conventional evaluator-entry checks and a byte-forwarding data reader do not establish closure. Refusing active content or genuinely confining code under S2.2-11 remain bounded possibilities, without an evidenced complete positive C7 integration. The conditional failure does not prove every system must expose these capabilities, so no system-wide NOT-CLOSABLE conclusion follows; D is not a demonstrated escape from the premise. [Evidence and limits](fix-b1-2/evidence-audit.md).'
assert old in text;text=text.replace(old,new)
text=text.replace('A passive or macro-disabled editor preserves document editing.','A passive or macro-disabled editor is a candidate for preserving document editing outside a D-restricted session. If D is imposed on the whole session, the editor inherits the loss of unrecorded document-file reads; ordinary document editing through that route is lost. Selective interpreter enforcement that retains those editor reads is unestablished.')
text=text.replace('D retains only bounded declared-file execution: scripts lose read access to unrecorded documents and project data.','If D is entered, scripts lose new file-open access to unrecorded documents and project data; mandatory entry on every start is not evidenced. Scripts still receive unrecorded bytes through stdin, argv/environment, inherited descriptors and socket/IPC input. D therefore does not establish safe declared-file execution against custom dispatch over those inputs.')
text=text.replace('Such data workflows are unavailable unless a separately evidenced mediated reader and language/authority restriction prevents returned values from becoming own-rights code; a byte-forwarding reader alone is insufficient.','Direct file-read workflows are unavailable in D. Alternative input routes can still deliver the same data, but their conversion into own-rights code remains unclosed; a separately evidenced language/authority restriction is missing, and a byte-forwarding reader alone is insufficient.')
text=text.replace('Under D, build and runtime scripts cannot read unrecorded project data or user documents; a separately constrained reader is unestablished, so those workflows are unavailable under the evidenced control;','If D is entered, build and runtime scripts cannot newly open unrecorded project-data or user-document files, but still receive unrecorded bytes through stdin, argv/environment, inherited descriptors and socket/IPC input. Neither mandatory entry nor safe mediation of these non-file routes is evidenced; direct file-read workflows are lost under D while custom-dispatch closure remains UNKNOWN;')
p.write_text(text)
(out/'row-changes.json').write_text(json.dumps(changes,indent=2)+'\n')
(out/'variant-inventory.json').write_text(json.dumps([dict(zip(['variant','requirement','verdict','mechanism','evidence','cost'],r)) for r in rows],indent=2)+'\n')
p=root/'DESIGN-INPUT.md';text=(out/'before/B1/DESIGN-INPUT.md').read_text().replace('# Design input after FX-B1-1','# Design input after FX-B1-2')
a=text.index('1. **Bounded native/file controls.**');b=text.index('\n2. **Declaration',a)
text=text[:a]+'''1. **Native primitives and conditional file controls.** Immutable code, execution/mapping authorization, native memory restrictions and revocation remain documented subcontrols. D supplies file-open denial only for processes that enter or inherit its domain; a mandatory component covering every interpreter launch is not evidenced. If imposed on the whole session, its document/project-data read denial also reaches the shell and descendant editors. D does not sanitize stdin, argv/environment, inherited descriptors or socket/IPC instruction streams, including custom dispatch in C7.24. F/I cooperation and selective mandatory placement remain UNKNOWN. No complete positive C7 integration is established. [Sources: raw/c7-sources.md E1–12; fix-b1-2/evidence-audit.md.]'''+text[b:]
text=text.replace('These are candidate responsibilities, not a proven minimal implementation.','These are candidate responsibilities, not a proven minimal implementation. All channel verdicts now follow their full R requirement; none is certified closed merely from its subcontrol. Whole-state lifecycle and runtime-port obligations remain applicable. The eight CLOSABLE mechanics rows retain their explicitly narrower requirements.')
a=text.index('- **C1.1 —');b=text.index('\nQ2 is an additional',a)
text=text[:a]+'\n'.join(f"- **{r[0].split()[0]} — {r[2]}:** {r[0].split(' ',1)[1]}." for r in rows if r[2]!='CLOSABLE')+'\n'+text[b:]
text=text.replace('Under D, scripts and dependency/build code lose reads of unrecorded user documents and project data. A mediated reader is unestablished; forwarding arbitrary bytes to arbitrary admitted scripts would recreate the custom-dispatch failure.','After entry into D, scripts and dependency/build code lose new opens of unrecorded user-document and project-data files. Whole-session inheritance also denies these reads to descendant editors, so document editing is not preserved by that blanket arrangement. Selective mandatory entry is unestablished. Scripts still receive bytes through stdin, argv/environment, inherited descriptors and socket/IPC input; forwarding those bytes to admitted own-rights dispatchers retains the conditional failure. Safe mediation is unestablished.')
text=text.replace('Frozen inputs are preserved and hashed; report checks are in fix-b1-1/validation.json. Separate acceptance review remains outstanding.','Round 2 preserves prior outputs and hashes all existing inputs in fix-b1-2/input-manifest.json; only report consistency checks were rerun, into fix-b1-2/validation.json. The current disposition is FIX-B1-2.md; separate review is recorded in fix-b1-2/REVIEW.md.')
p.write_text(text)
print(json.dumps({'rows':len(rows),'counts':counts,'changed_rows':len(changes),'verdict_changes':sum(x['before'][2]!=x['after'][2] for x in changes)}))
